import random

class Lottery:
    def __init__(self):
        self.tickets = []
        self.prize_pool = []

    def add_ticket(self, ticket):
        self.tickets.append(ticket)

    def add_prize(self, prize):
        self.prize_pool.append(prize)

    def draw(self):
        winner = random.choice(self.tickets)

        for prize in self.prize_pool:
            if winner.has_prize(prize):
                winner.add_prize(prize)
                self.prize_pool.remove(prize)

        return winner

