import random

def print_options():
    print("1. Change")
    print("2. Addition")
    print("3. Subtraction")
    print("4. Multiplication")

def addition():
    num1 = random.randint(0, 100)
    num2 = random.randint(0, 100)
    print(f"{num1} + {num2} = ?")

def subtraction():
    num1 = random.randint(100, 200)
    num2 = random.randint(0, 100)
    print(f"{num1} - {num2} = ?")

def multiplication():
    num1 = random.randint(1000, 2000)
    num2 = random.randint(1000, 2000)
    print(f"{num1} * {num2} = ?")

