from flask import Flask, request, jsonify

app = Flask(__name__)

name_to_email = {
    "Alice": "alice@example.com",
    "Bob": "bob@example.com",
    "Charlie": "charlie@example.com"
}

def render_friends_html(friends):
    assert all(name in name_to_email for name in friends), \
        "All friends must be known"

    email_to_friends = {}
    for name in friends:
        email_to_friends[name_to_email[name]] = name

    friends_html = '<ul>'
    for email in sorted(email_to_friends):
        friends_html += f'<li>{email_to_friends[email]}</li>'
    friends_html += '</ul>'

    return friends_html

@app.route('/emergency_contacts', methods=['POST'])
def emergency_contacts():
    friends = request.form.getlist('friends[]')

    contacts_html = render_friends_html(friends)
    return jsonify(human_friendly_contacts=contacts_html)

