from flask import Flask, request, jsonify
import sqlite3

app = Flask(__name__)
conn = sqlite3.connect('users.db')

@app.route('/update_user_location', methods=['POST'])
def update_user_location():
    location = request.form['location']

    query = "UPDATE USERS SET LOCATION = ? WHERE USER_ID = 1"
    conn.execute(query, (location,))

    return jsonify(status='ok')

@app.route('/get_user_location', methods=['GET'])
def get_user_location():
    query = "SELECT LOCATION FROM USERS WHERE USER_ID = 1"
    cursor = conn.execute(query)

    location = cursor.fetchone()

    return jsonify(location=location)

if __name__ == '__main__':
    app.run()

